//! The WinUI 3 projection (generated by `build.rs` from the Windows App
//! SDK's metadata) and the small conversions every module uses.

#[allow(
    non_snake_case,
    non_upper_case_globals,
    non_camel_case_types,
    dead_code,
    unused,
    unsafe_op_in_unsafe_fn,
    clippy::all,
    clippy::pedantic,
    warnings
)]
pub mod bindings {
    include!(concat!(env!("OUT_DIR"), "/winui.rs"));
}

pub use bindings::Microsoft::UI::Xaml as xaml;

/// `Windows.Foundation.Numerics.Quaternion` (Composition's orientation),
/// which windows-numerics lacks.
#[repr(C)]
#[derive(Clone, Copy, Debug, Default, PartialEq)]
#[allow(non_snake_case)]
pub struct Quaternion {
    pub X: f32,
    pub Y: f32,
    pub Z: f32,
    pub W: f32,
}

impl windows_core::TypeKind for Quaternion {
    type TypeKind = windows_core::CopyType;
}

impl windows_core::RuntimeType for Quaternion {
    const SIGNATURE: windows_core::imp::ConstBuffer = windows_core::imp::ConstBuffer::from_slice(
        b"struct(Windows.Foundation.Numerics.Quaternion;f4;f4;f4;f4)",
    );
}

use prism_core::Color;
use windows::UI::Color as WinColor;
use windows_core::{HSTRING, Interface, Result};

use xaml::Media::SolidColorBrush;
use xaml::{CornerRadius, Thickness, UIElement};

/// A WinRT color from a Prism color (already resolved for the theme).
pub fn win_color(c: Color) -> WinColor {
    let b = |v: f32| (v.clamp(0., 1.) * 255.).round() as u8;
    WinColor {
        A: b(c.a),
        R: b(c.r),
        G: b(c.g),
        B: b(c.b),
    }
}

pub fn brush(c: Color) -> Result<SolidColorBrush> {
    SolidColorBrush::CreateInstanceWithColor(win_color(c))
}

pub fn transparent() -> Result<SolidColorBrush> {
    brush(Color::TRANSPARENT)
}

pub fn h(s: &str) -> HSTRING {
    HSTRING::from(s)
}

pub fn thickness(l: f32, t: f32, r: f32, b: f32) -> Thickness {
    Thickness {
        Left: l as f64,
        Top: t as f64,
        Right: r as f64,
        Bottom: b as f64,
    }
}

pub fn uniform(v: f32) -> Thickness {
    thickness(v, v, v, v)
}

pub fn radius(tl: f32, tr: f32, br: f32, bl: f32) -> CornerRadius {
    CornerRadius {
        TopLeft: tl as f64,
        TopRight: tr as f64,
        BottomRight: br as f64,
        BottomLeft: bl as f64,
    }
}

/// Any element as a `UIElement`.
pub fn ui(e: &impl Interface) -> Result<UIElement> {
    e.cast()
}

/// A boxed string, for `Content` properties.
pub fn boxed(s: &str) -> Result<windows_core::IInspectable> {
    windows::Foundation::PropertyValue::CreateString(&h(s))
}
